// This parser is only for tier0-opcua-subscribe batch + compact output.
if (msg.opcua?.operation !== 'change' || !Array.isArray(msg.payload)) {
    return [null, msg]; // Startup, command and recovery status is not telemetry.
}
const topicMap = {
    'ns=2;s=Temperature': { topic: 'Plant/Line1/Metric/Temperature', field: 'temperature' },
    'ns=2;s=Running': { topic: 'Plant/Line1/State/Running', field: 'running' },
    'ns=2;s=ProductionCount': { topic: 'Plant/Line1/Metric/ProductionCount', field: 'count' }
};
const messages = [];
const diagnostics = [];
for (const change of msg.payload) {
    const target = change && topicMap[change.nodeId];
    if (!target || change.statusCode !== 'Good' || change.value === undefined || change.value === null) {
        diagnostics.push({ payload: change, opcua: msg.opcua, reason: !target ? 'unmapped-point' : 'quality-or-value' });
        continue;
    }
    // Values are already decoded. Preserve 0, false and large-integer strings.
    // Match UNS field types; do not coerce values with Number().
    messages.push({ topic: target.topic, payload: JSON.stringify({ [target.field]: change.value }) });
}
const queue = msg.opcua.queue;
if (queue && (queue.dropped > 0 || queue.coalesced > 0)) {
    diagnostics.push({ opcua: msg.opcua, reason: 'queue-diagnostics' });
}
return [messages.length ? messages : null, diagnostics.length ? diagnostics : null];
